from jsonb_to_recordset($wall_questions$[{"id":"u01_l06_q162","lesson_id":"u01_l06","difficulty":"hard","prompt":"لماذا لا يصح أن يتوسع الاجتهاد ليغيّر أنصبة الميراث المقررة بالنص؟","options":[{"id":"o3","text":"لأن كل مسألة مالية خارج الدين"},{"id":"o4","text":"لأن الاجتهاد يجري دون قواعد"},{"id":"o1","text":"لأن النص القطعي حسم حكمها فلا مجال لاستنباط حكم يناقضه"},{"id":"o2","text":"لأن الميراث لا يتعلق بالحقوق"}],"correct_id":"o1","explanation":"ذكر الدرس نصيب الورثة من مسائل الأحكام القطعية غير القابلة للاجتهاد.","page":42},{"id":"u01_l06_q163","lesson_id":"u01_l06","difficulty":"medium","prompt":"ما الذي يلزم المجتهد قبل إصدار حكم في تقنية حديثة لم تتضح حقيقتها؟","options":[{"id":"o2","text":"أن يصدر الحكم قبل تصور الواقعة"},{"id":"o4","text":"أن يتجاهل آثار التقنية في المجتمع"},{"id":"o3","text":"أن يعتمد على الخبر غير الموثوق فقط"},{"id":"o1","text":"أن يفهم تفاصيل المسألة ويستعين بالمختصين عند الحاجة"}],"correct_id":"o1","explanation":"أكد الكتاب أن الحكم على الشيء فرع من تصوره وأنه يجوز الرجوع للمتخصصين.","page":43},{"id":"u01_l06_q164","lesson_id":"u01_l06","difficulty":"hard","prompt":"طالب قادر على حفظ النصوص لكنه لا يفهم أصول الفقه؛ ما الجانب الذي ينقصه للاجتهاد؟","options":[{"id":"o3","text":"القدرة على الخطابة دون استدلال"},{"id":"o2","text":"حفظ أسماء المدن التاريخية فقط"},{"id":"o4","text":"معرفة أنواع الألعاب التعليمية"},{"id":"o1","text":"معرفة قواعد الاستنباط والأصول التي تُفهم بها الأدلة"}],"correct_id":"o1","explanation":"ذكر الدرس العلم بأصول الفقه وقواعده ضمن شروط أهلية المجتهد.","page":43},{"id":"u01_l06_q165","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي وصف يحدد الفارق بين الفتوى الجماعية والجواب الفردي في صورة المجامع الحديثة؟","options":[{"id":"o3","text":"إلغاء مشاركة المختصين في الوقائع"},{"id":"o4","text":"منع الاطلاع على البحوث السابقة"},{"id":"o2","text":"اعتماد القرار على قرعة بين الأعضاء"},{"id":"o1","text":"مناقشة مجموعة مؤهلة للأدلة والوصول إلى رأي يتفق عليه الحاضرون أو أكثرهم"}],"correct_id":"o1","explanation":"عرّف الدرس الاجتهاد الجماعي بعرض المسألة والمناقشة واتفاق الحاضرين أو أغلبهم.","page":44},{"id":"u01_l06_q166","lesson_id":"u01_l06","difficulty":"hard","prompt":"لماذا يسهم اشتراك الأطباء والاقتصاديين مع الفقهاء في بعض قضايا الاجتهاد الجماعي؟","options":[{"id":"o4","text":"لأن الخبرة العلمية تمنع النقاش الفقهي"},{"id":"o3","text":"لأن كل اختصاص يمنح صاحبه حق تغيير النص القطعي"},{"id":"o1","text":"لأن فهم الحقائق المتخصصة يساعد الفقيه على تصور القضية بدقة"},{"id":"o2","text":"لأن رأي المختص يحل محل الأدلة الشرعية"}],"correct_id":"o1","explanation":"بيّن الكتاب أن مشاركة الاختصاصات المختلفة تضيء حقائق المسألة للفقهاء.","page":44},{"id":"u01_l06_q168","lesson_id":"u01_l06","difficulty":"hard","prompt":"لماذا تعد مجلة الأبحاث المحكمة التي تصدرها دائرة الإفتاء عملًا متصلًا بوظيفتها العلمية؟","options":[{"id":"o3","text":"لأنها تمنع النظر في القضايا المستجدة"},{"id":"o2","text":"لأنها تستبدل أحكام الشريعة بالتصويت الشعبي"},{"id":"o1","text":"لأنها تسهم في نشر الدراسات الشرعية الموثقة وتطوير البحث"},{"id":"o4","text":"لأنها تخصصت بإعلانات التجارة فقط"}],"correct_id":"o1","explanation":"ورد إصدار مجلة علمية محكمة ضمن مهام دائرة الإفتاء العام الأردنية.","page":45},{"id":"u01_l06_q174","lesson_id":"u01_l06","difficulty":"medium","prompt":"لماذا يُطلب من المجتهد فهم واقع القضية الجديدة قبل الحكم عليها؟","options":[{"id":"o2","text":"لأن فهم الواقع يغني عن الأدلة الشرعية"},{"id":"o4","text":"لأن سؤال الخبراء يمنع الاجتهاد"},{"id":"o1","text":"لأن الحكم على الشيء فرع عن تصوره تصورًا صحيحًا"},{"id":"o3","text":"لأن كل واقعة مستجدة لها الحكم نفسه"}],"correct_id":"o1","explanation":"بيّن الدرس ضرورة التصور الدقيق للمسألة والاستعانة بالمتخصصين.","page":43},{"id":"u01_l06_q176","lesson_id":"u01_l06","difficulty":"medium","prompt":"لماذا يستفيد الاجتهاد الجماعي في القضايا الطبية من مشاركة الأطباء مع الفقهاء؟","options":[{"id":"o4","text":"ليُترك القرار لغير المؤهلين من جميع المجالات"},{"id":"o2","text":"ليصبح الطب بديلًا تامًا عن الأحكام الشرعية"},{"id":"o1","text":"ليتضح واقع المسألة طبيًا قبل تنزيل الحكم الشرعي عليها"},{"id":"o3","text":"لأن الاجتهاد لا يجوز فيه استعمال الأدلة"}],"correct_id":"o1","explanation":"ذكر الدرس أن الاستعانة بأهل الاختصاص تكشف حقائق المسائل المعروضة.","page":44},{"id":"u01_l06_q185","lesson_id":"u01_l06","difficulty":"medium","prompt":"ما الميزة التي يضيفها التواصل بين علماء البلدان إلى الاجتهاد الجماعي المعاصر؟","options":[{"id":"o4","text":"جعل سرعة الإجابة أهم من الدليل"},{"id":"o2","text":"إلغاء اختلاف التخصصات جميعًا"},{"id":"o3","text":"الاستغناء عن دراسة النصوص الشرعية"},{"id":"o1","text":"تبادل النظر والخبرات في القضايا المستجدة"}],"correct_id":"o1","explanation":"أشار الكتاب إلى أثر تطور التواصل في الصورة المؤسسية للاجتهاد الجماعي.","page":44},{"id":"u01_l06_q186","lesson_id":"u01_l06","difficulty":"hard","prompt":"إذا اجتمع فقيه وطبيب لدراسة إجراء علاجي مستجد، فأي مسار يتفق مع الاجتهاد الجماعي؟","options":[{"id":"o1","text":"تعاون الاختصاصين لفهم الواقعة وحكمها"},{"id":"o3","text":"إهمال المعلومات المتعلقة بأثر العلاج"},{"id":"o4","text":"استبدال التثبت بتصويت غير مؤسس"},{"id":"o2","text":"انفراد غير المختص بالحكم على التفاصيل الطبية"}],"correct_id":"o1","explanation":"يستفيد الاجتهاد الجماعي من معرفة أهل الاختصاص بالوقائع التي تتعلق بالحكم.","page":44},{"id":"u02_l01_q114","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الذي يبينه جمع النص القرآني بين الفواحش الظاهرة والباطنة؟","options":[{"id":"o1","text":"أن اجتنابها واجب في السر والعلن"},{"id":"o3","text":"أن النية تبيح الفواحش في الخفاء"},{"id":"o4","text":"أن الناس لا يحاسبون على الأفعال المستترة"},{"id":"o2","text":"أن الإثم يقع في العلن وحده"}],"correct_id":"o1","explanation":"وضح الشرح أن الله يعلم الفاحشة سواء وقعت في السر أم العلن.","page":51},{"id":"u02_l01_q115","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الموقف السليم ممن يحتج بتقليد آبائه لتبرير فعل محرّم بحسب التوسع؟","options":[{"id":"o1","text":"رفض الاحتجاج بالعادة أمام أمر الله"},{"id":"o3","text":"اتباع سلوك الآباء مهما كانت عواقبه"},{"id":"o4","text":"إلغاء مسؤولية الإنسان عن اختياره"},{"id":"o2","text":"اعتبار العادات أصلًا للتحليل والتحريم"}],"correct_id":"o1","explanation":"تناول الإثراء احتجاج الكافرين بتقليد الآباء لتبرير المعصية وردّ هذا الاحتجاج.","page":52},{"id":"u02_l01_q118","lesson_id":"u02_l01","difficulty":"hard","prompt":"شخص يحصر الذنوب الكبيرة في الأفعال الظاهرة ويستبعد الخفية؛ ما التصحيح من آيات الأعراف؟","options":[{"id":"o4","text":"كل فعل مستتر يصبح مباحًا"},{"id":"o2","text":"الأفعال الخفية لا تدخل ضمن المحرمات"},{"id":"o1","text":"التحريم يتناول الفواحش ما ظهر منها وما بطن"},{"id":"o3","text":"الجهر وحده معيار التحريم"}],"correct_id":"o1","explanation":"أكد شرح الفواحش أن وقوعها خفية لا يرفع عنها الحرمة.","page":51},{"id":"u02_l01_q123","lesson_id":"u02_l01","difficulty":"medium","prompt":"أي اقتران صحيح بين موضوع الآية وما تتناوله من سورة الأعراف؟","options":[{"id":"o3","text":"الآيتان 31 و32: أنصبة الميراث"},{"id":"o1","text":"الآية 33: اجتناب المحرمات"},{"id":"o4","text":"الآية 33: وصف مراحل خلق الجنين"},{"id":"o2","text":"الآية 34: أحكام الزكاة"}],"correct_id":"o1","explanation":"ربطت الخريطة موضوع الآية 33 باجتناب المحرمات.","page":49},{"id":"u02_l01_q131","lesson_id":"u02_l01","difficulty":"medium","prompt":"في التوجيه الوارد في التعلم القبلي، ما السلوك الذي يجمع الانتفاع بالطيبات مع تهذيب النفس؟","options":[{"id":"o1","text":"الأكل واللباس والصدقة دون إسراف أو تكبر"},{"id":"o2","text":"تحريم كل لباس جميل"},{"id":"o4","text":"المبالغة في الاستهلاك لإظهار النعمة"},{"id":"o3","text":"الإنفاق بقصد المباهاة"}],"correct_id":"o1","explanation":"ورد في الحديث التوجيه للأكل والشرب واللباس والصدقة دون إسراف أو مخيلة.","page":48},{"id":"u02_l01_q136","lesson_id":"u02_l01","difficulty":"medium","prompt":"تتضمن المحرمات في الآيات «الإثم» إلى جانب «الفواحش»؛ لماذا لا يعد اللفظان مترادفين تمامًا؟","options":[{"id":"o2","text":"لأن الإثم يعني اللباس الحسن"},{"id":"o4","text":"لأن الإثم مرادف للأجل"},{"id":"o3","text":"لأن الفواحش هي المباحات"},{"id":"o1","text":"لأن الإثم أعمّ من صورة مخصوصة من الفواحش"}],"correct_id":"o1","explanation":"يفصل شرح الكتاب بين الفواحش وغيرها من صور الإثم والمحرمات.","page":51},{"id":"u02_l01_q137","lesson_id":"u02_l01","difficulty":"hard","prompt":"موظف يستغل منصبه لأخذ رشوة ثم يسميها «مقابل خدمة»، فأي معنى من المحرمات ينطبق عليه؟","options":[{"id":"o1","text":"الاعتداء وأكل حقوق الناس بالباطل"},{"id":"o2","text":"أخذ الزينة عند المسجد"},{"id":"o3","text":"الاعتدال في الطعام"},{"id":"o4","text":"الرخصة في العبادة"}],"correct_id":"o1","explanation":"أورد الدرس الرشوة صورة للاعتداء على الحقوق ضمن البغي والإثم.","page":51},{"id":"u02_l01_q138","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الغرض البلاغي من الاستفهام عن تحريم زينة الله التي أخرج لعباده؟","options":[{"id":"o1","text":"إنكار تحريم ما أباحه الله بلا دليل"},{"id":"o2","text":"طلب معرفة أسماء الأطعمة"},{"id":"o3","text":"تقرير مشروعية الإسراف"},{"id":"o4","text":"الاستفهام عن موعد الساعة"}],"correct_id":"o1","explanation":"نص الصندوق اللغوي على أن الاستفهام إنكاري على من يحرم بغير دليل.","page":52},{"id":"u02_l01_q139","lesson_id":"u02_l01","difficulty":"hard","prompt":"مجتمع يرى في تأخر العقوبة دليلًا على أن مخالفاته لا عاقبة لها؛ بأي توجيه ترد عليه الآية (34)؟","options":[{"id":"o2","text":"تحديد الموعد الدقيق لنهاية الأمة"},{"id":"o3","text":"الامتناع عن بناء أسباب القوة"},{"id":"o4","text":"حصر الجزاء بالدنيا وحدها"},{"id":"o1","text":"عدم الاغترار بالإمهال والمبادرة إلى الطاعة"}],"correct_id":"o1","explanation":"يذكر الشرح أن الأجل المحدد يبعث على الطاعة وعدم الاغترار بإمهال الله.","page":52},{"id":"u02_l01_q140","lesson_id":"u02_l01","difficulty":"medium","prompt":"بماذا يختلف الاجتهاد في تقدير المصلحة عن ادعاء أن الله أمر بمعصية لتبريرها؟","options":[{"id":"o2","text":"كلاهما من الترخيص المستحب"},{"id":"o1","text":"الأول بحث منضبط والثاني نسبة قول إلى الله بلا علم"},{"id":"o3","text":"كلاهما اتباع للآيات دون فهم"},{"id":"o4","text":"الثاني هو الأصل في تحديد الأحكام"}],"correct_id":"o1","explanation":"رفض الدرس تبرير الفواحش بالادعاء أن الله أمر بها.","page":52},{"id":"u02_l01_q144","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الخلل في قول إن الأصل تحريم الطعام حتى يرد دليل خاص بإباحة كل صنف؟","options":[{"id":"o3","text":"لأن الإسراف مطلوب في الأطعمة"},{"id":"o2","text":"لأن جميع المطعومات محرمة بإطلاق"},{"id":"o4","text":"لأن حكم الطعام من أحكام الميراث"},{"id":"o1","text":"لأنه يعكس قاعدة الإباحة الأصلية إلا ما دل الدليل على تحريمه"}],"correct_id":"o1","explanation":"وردت قاعدة الأصل في الأشياء الإباحة إلا ما حرمه الشرع، ومنها المطعومات والمشروبات.","page":50},{"id":"u02_l01_q146","lesson_id":"u02_l01","difficulty":"medium","prompt":"إذا وقع فعل محرّم في الخفاء، فلماذا لا يخرج عن نطاق التحريم في شرح الآية (33)؟","options":[{"id":"o2","text":"لأن الحكم يزول باختفاء الناس"},{"id":"o1","text":"لأن التحريم يشمل ما ظهر من الفواحش وما بطن"},{"id":"o3","text":"لأن التحريم مقصور على العلن"},{"id":"o4","text":"لأن ما يقع في الخفاء لا أثر له"}],"correct_id":"o1","explanation":"ذكر الدرس أن الفواحش محرمة ظاهرها وباطنها، وأن الله تعالى يعلمها.","page":51},{"id":"u02_l01_q147","lesson_id":"u02_l01","difficulty":"hard","prompt":"ما الرابط بين منع نسبة حكم إلى الله بغير دليل والنهي عن تحريم زينته التي أخرج لعباده؟","options":[{"id":"o3","text":"إلغاء كل حكم يتعلق بالمباحات"},{"id":"o2","text":"إباحة الكذب إذا رآه الناس مناسبًا"},{"id":"o1","text":"حماية التشريع من ادعاء أحكام لا دليل عليها"},{"id":"o4","text":"ربط التحريم برأي الأكثرية وحده"}],"correct_id":"o1","explanation":"من المحرمات القول على الله بغير علم، كما أنكرت الآيات تحريم ما أباحه دون دليل.","page":52},{"id":"u02_l01_q151","lesson_id":"u02_l01","difficulty":"easy","prompt":"ما المعنى الذي أورده صندوق المفردات للتعبير الدال على مجاوزة الحد في الآية (31)؟","options":[{"id":"o4","text":"التوسع في حق الانتخاب"},{"id":"o1","text":"تجاوز المقدار المعتاد في الانتفاع بالنعم"},{"id":"o3","text":"السفر من مكان إلى آخر"},{"id":"o2","text":"ترك جميع أنواع الطعام المباح"}],"correct_id":"o1","explanation":"شرح صندوق المفردات أن النهي متعلق بمجاوزة الحد المعتاد.","page":49},{"id":"u02_l01_q152","lesson_id":"u02_l01","difficulty":"medium","prompt":"أراد شخص أن يلبس لباسًا جميلًا ساترًا عند الصلاة؛ ما الفهم الصحيح لهذه الرغبة؟","options":[{"id":"o4","text":"الزينة لا تشمل إلا الأموال والمجوهرات"},{"id":"o1","text":"الزينة المباحة من تعظيم شأن العبادة دون إسراف"},{"id":"o3","text":"ستر العورة غير مطلوب في المسجد"},{"id":"o2","text":"اللباس الجميل محرم في كل صلاة"}],"correct_id":"o1","explanation":"شرح الكتاب الزينة بأنها اللباس الساتر الجميل وأشار إلى مكانة بيوت الله.","page":50},{"id":"u02_l01_q155","lesson_id":"u02_l01","difficulty":"medium","prompt":"إقدام مسؤول على خيانة أمانة الناس، في أي وصف من أوصاف المحرمات الذي عرضته الآية يدخل؟","options":[{"id":"o1","text":"البغي والتعدي على حقوق الآخرين"},{"id":"o2","text":"الزينة المشروعة عند المسجد"},{"id":"o4","text":"الاستئذان المشروع قبل الدخول"},{"id":"o3","text":"الانتفاع المعتدل بالطعام"}],"correct_id":"o1","explanation":"عدّ الكتاب خيانة الأمانة من صور البغي والظلم على الآخرين.","page":51},{"id":"u02_l01_q156","lesson_id":"u02_l01","difficulty":"hard","prompt":"لماذا يتضمن وصف الشرك بأنه اتخاذ ند لله جانبًا يتجاوز مجرد الخطأ الأخلاقي بين الناس؟","options":[{"id":"o2","text":"لأنه اختلاف في نوع الطعام فقط"},{"id":"o4","text":"لأنه اختلاف في طريقة السكن"},{"id":"o1","text":"لأنه تعلق بحق الله في العبودية والربوبية"},{"id":"o3","text":"لأنه متعلق بشروط بيع السلع"}],"correct_id":"o1","explanation":"فسّر الدرس الشرك بجعل ند أو شريك لله في العبودية والربوبية.","page":51},{"id":"u02_l01_q161","lesson_id":"u02_l01","difficulty":"medium","prompt":"بماذا يفسر صندوق المفردات في الآيات تعبير اتخاذ الزينة عند المسجد؟","options":[{"id":"o4","text":"ترك ستر العورة بحجة البساطة"},{"id":"o1","text":"ارتداء اللباس الساتر المناسب"},{"id":"o2","text":"الامتناع عن دخول بيوت الله"},{"id":"o3","text":"شراء ثياب مرتفعة الثمن لذاتها"}],"correct_id":"o1","explanation":"بينت مفردات الآيات أن المقصود التزين باللباس الساتر.","page":49},{"id":"u02_l01_q163","lesson_id":"u02_l01","difficulty":"hard","prompt":"ادّعى أحدهم أن كل طعام لم يرد نص بإباحته ممنوع؛ أي قاعدة من شرح الآيات تردّ قوله؟","options":[{"id":"o1","text":"الأصل في المطعومات والمشروبات الإباحة إلا ما ورد بتحريمه دليل"},{"id":"o2","text":"الأصل تحريم جميع الأطعمة حتى يصنعها المرء بنفسه"},{"id":"o3","text":"الإسراف مباح في الطعام المباح"},{"id":"o4","text":"التحريم يكون بالذوق الشخصي لا بالدليل"}],"correct_id":"o1","explanation":"قرر الدرس إباحة المطعومات والمشروبات إلا ما ورد الدليل على تحريمه.","page":50},{"id":"u02_l01_q168","lesson_id":"u02_l01","difficulty":"medium","prompt":"أجاز شخص لنفسه نسبة تحريم إلى الله دون نص؛ في أي محرم يندرج فعله؟","options":[{"id":"o2","text":"الاعتدال في التمتع بالطيبات"},{"id":"o3","text":"تعظيم المسجد باللباس الحسن"},{"id":"o4","text":"التعجيل بالأعمال الصالحة"},{"id":"o1","text":"القول على الله بغير علم"}],"correct_id":"o1","explanation":"صنف الدرس افتراء أحكام على الله من القول عليه بغير علم.","page":52},{"id":"u02_l01_q174","lesson_id":"u02_l01","difficulty":"medium","prompt":"لماذا يُعد الإسراف في استهلاك الماء والطعام مخالفًا لتوجيه الآيات؟","options":[{"id":"o1","text":"لما فيه من ضرر واستنزاف للثروات والمقدرات"},{"id":"o3","text":"لأنه يحافظ على الموارد من النفاد"},{"id":"o4","text":"لأنه يساوي الاقتصاد في النفقات"},{"id":"o2","text":"لأنه دليل على الاهتمام بالآخرين دائمًا"}],"correct_id":"o1","explanation":"علّل الدرس النهي عن الإسراف بالضرر واستنزاف الموارد.","page":50},{"id":"u02_l01_q176","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الذي يوضحه ردّ القرآن على تقليد الآباء دون دليل في سياق سورة الأعراف؟","options":[{"id":"o1","text":"أن التقليد الأعمى لا يبرر الذنوب ولا يغني عن الحق والدليل"},{"id":"o4","text":"أن الإنسان لا يتحمل مسؤولية خياراته"},{"id":"o2","text":"أن فعل الأسلاف يصبح مباحًا بمجرد شيوعه"},{"id":"o3","text":"أن العادات تكفي وحدها لتحديد الحلال والحرام"}],"correct_id":"o1","explanation":"أوضح الإثراء رفض الاحتجاج بتقليد الآباء والأجداد في ارتكاب المخالفات دون بصيرة.","page":52},{"id":"u02_l01_q178","lesson_id":"u02_l01","difficulty":"easy","prompt":"ما الموقف الذي تنتقده الآيات عند نسبة تحليل أو تحريم إلى الله دون دليل؟","options":[{"id":"o4","text":"احترام حرمة المسجد"},{"id":"o2","text":"الحرص على أداء الصلاة"},{"id":"o3","text":"الاعتدال في الإنفاق"},{"id":"o1","text":"الافتراء على الله تعالى"}],"correct_id":"o1","explanation":"نص الشرح على أن نسبة أحكام إلى الله لم يقل بها من الكذب والافتراء عليه.","page":52},{"id":"u02_l01_q181","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما المقصود بالنهي عن مجاوزة الحد المعتاد في آيات الأعراف عند تناول المباحات؟","options":[{"id":"o2","text":"تحريم كل ما فيه زينة ولو كان مباحًا"},{"id":"o1","text":"تجنب الإسراف مع بقاء أصل إباحة الطيبات"},{"id":"o3","text":"منع الطعام والشراب في الحياة اليومية"},{"id":"o4","text":"حصر الاعتدال في أيام الصيام وحدها"}],"correct_id":"o1","explanation":"فسر الدرس النهي عن الإسراف بعد إباحة الطعام والشراب بأنه عدم تجاوز الحد المعتاد.","page":49},{"id":"u02_l01_q182","lesson_id":"u02_l01","difficulty":"medium","prompt":"لماذا خصت الآية المسجد بذكر الزينة مع عموم الاهتمام باللباس؟","options":[{"id":"o1","text":"تعظيم مكانة بيوت الله والتحفيز على احترامها"},{"id":"o3","text":"لأن الزينة تعني المبالغة في الثمن"},{"id":"o2","text":"لأن ستر العورة لا يلزم خارج المسجد مطلقًا"},{"id":"o4","text":"لأن دخول المسجد يمنع لباسًا ساترًا جميلًا"}],"correct_id":"o1","explanation":"ذكر الكتاب أن تخصيص المسجد يذكّر بعظمة بيوت الله ويحفز على تعظيمها.","page":50},{"id":"u02_l01_q185","lesson_id":"u02_l01","difficulty":"medium","prompt":"لماذا يقترن تحريم الاعتداء على حقوق الآخرين بتحريم الفواحش في شرح الآيات؟","options":[{"id":"o4","text":"لأن الاعتداء لا يتصل بالتكليف الديني"},{"id":"o3","text":"لأن الفواحش مباحة عند رضا المجتمع"},{"id":"o2","text":"لأن الحقوق ليست جزءًا من الأخلاق"},{"id":"o1","text":"لأن توجيه الآيات يشمل صلاح السلوك الشخصي والاجتماعي"}],"correct_id":"o1","explanation":"عرض الدرس مجموعة محرمات تحفظ الأخلاق والحقوق وتمنع العدوان.","page":51},{"id":"u02_l01_q186","lesson_id":"u02_l01","difficulty":"medium","prompt":"ما الذي يدل عليه ذكر أجل الأمم إلى جانب أجل الأفراد في سورة الأعراف؟","options":[{"id":"o4","text":"أن لأجل الأمة صلة بالطعام وحده"},{"id":"o2","text":"أن الأمم لا تمر بالتغير أو الزوال"},{"id":"o1","text":"أن للأفراد والجماعات مددًا مقدرة لا تتقدم ولا تتأخر عن أجلها"},{"id":"o3","text":"أن الإنسان يعرف أجله بمجرد عمره"}],"correct_id":"o1","explanation":"بينت الآية 34 في الدرس أن للأمم آجالًا محددة كما للأفراد.","page":52},{"id":"u02_l01_q188","lesson_id":"u02_l01","difficulty":"medium","prompt":"إذا طُلب تحديد نوع الاستفهام في الإنكار على تحريم زينة الله المباحة، فأي توصيف يناسب السياق؟","options":[{"id":"o4","text":"استفهام يحدد زمن قيام الساعة"},{"id":"o2","text":"استفهام لطلب معرفة العدد فقط"},{"id":"o1","text":"استفهام إنكاري يرد التحريم بغير حق"},{"id":"o3","text":"استفهام يتضمن إباحة الكذب على الله"}],"correct_id":"o1","explanation":"تعرض مراجعة الدرس دلالة الاستفهام المتعلق بزينة الله والطيبات.","page":54},{"id":"u02_l02_q092","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا لا تُعد المنفعة المالية المتحصلة من أمر محرم مصلحة معتبرة؟","options":[{"id":"o1","text":"لأن الشرع قد ألغى اعتبار تلك المنفعة"},{"id":"o4","text":"لأن المنفعة الخاصة تغلب كل حكم"},{"id":"o2","text":"لأن كل مال مكتسب محرم"},{"id":"o3","text":"لأن الربح لا يتعلق بالمصالح أصلًا"}],"correct_id":"o1","explanation":"يصنف الدرس المنافع التي رفضها الشرع مصالح ملغاة.","page":56},{"id":"u02_l02_q105","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا يعد نظر الخاطب إلى المخطوبة من المصالح المعتبرة؟","options":[{"id":"o3","text":"لأن منفعة شخص واحد تبيح كل شيء"},{"id":"o1","text":"لوجود دليل يراعي الألفة والمودة بينهما"},{"id":"o2","text":"لأنه ممارسة بلا ضابط أو أساس شرعي"},{"id":"o4","text":"لأن الضرر هو المقصد من هذا الحكم"}],"correct_id":"o1","explanation":"ذكر الدرس هذا المثال ضمن المصلحة التي قبلها الشرع.","page":56},{"id":"u02_l02_q107","lesson_id":"u02_l02","difficulty":"medium","prompt":"أي ضابط يُستعمل حين يظن شخص أن نفعه الخاص يبيح الإضرار بعموم الناس؟","options":[{"id":"o2","text":"اعتبار المنفعة الخاصة معيارًا وحيدًا"},{"id":"o4","text":"قبول كل ادعاء بلا فحص"},{"id":"o1","text":"تقديم المصلحة العامة وعدم الإضرار بالمجموع"},{"id":"o3","text":"إلغاء اشتراط حقيقة المصلحة"}],"correct_id":"o1","explanation":"يشترط الكتاب عموم المصلحة وألا تكون وهمية.","page":58},{"id":"u02_l02_q109","lesson_id":"u02_l02","difficulty":"hard","prompt":"اقتُرح حكم يحقق نفعًا ماليًا كبيرًا لكنه يصادم نصًا قطعيًا؛ كيف يصنف وفق ضابط المصالح؟","options":[{"id":"o3","text":"يقدم على الحكم النصي تلقائيًا"},{"id":"o2","text":"يقبل بمجرد ارتفاع الربح"},{"id":"o4","text":"يصبح مصلحة مرسلة مهما كانت المعارضة"},{"id":"o1","text":"لا يعد مصلحة معتبرة لمعارضته النص"}],"correct_id":"o1","explanation":"يمنع ضابط عدم المعارضة اعتبار المصلحة التي تصادم نصًا أو إجماعًا.","page":58},{"id":"u02_l02_q114","lesson_id":"u02_l02","difficulty":"medium","prompt":"شخص يقترح تعديل أنصبة الميراث الثابتة بحجة المصلحة؛ لماذا يرفض اقتراحه وفق الضوابط؟","options":[{"id":"o3","text":"لأن كل تصرف مالي مرفوض"},{"id":"o4","text":"لأنه يحقق منفعة عامة بالضرورة"},{"id":"o2","text":"لأنه يتعلق بمال قليل"},{"id":"o1","text":"لمعارضته حكمًا مقررًا بنص شرعي"}],"correct_id":"o1","explanation":"ضرب الكتاب هذا المثال على رفض المصلحة التي تعارض نصًا أو إجماعًا.","page":58},{"id":"u02_l02_q115","lesson_id":"u02_l02","difficulty":"medium","prompt":"ما الضابط الذي يرفض مصلحة تجارية لفرد تؤدي إلى إضرار مجموع الناس؟","options":[{"id":"o2","text":"إباحة أي ربح مهما كانت الوسيلة"},{"id":"o1","text":"عمومية المصلحة وعدم حصرها في نفع فردي مضر"},{"id":"o4","text":"الاكتفاء بالظن في تقدير النفع"},{"id":"o3","text":"تقديم منفعة الفرد دائمًا على الجميع"}],"correct_id":"o1","explanation":"اشترط الكتاب أن تحقق المصلحة منفعة عامة وألا تضر بالمجموع لمصلحة فرد.","page":58},{"id":"u02_l02_q117","lesson_id":"u02_l02","difficulty":"medium","prompt":"أي تمييز يوضح مفهوم جلب المصالح ودفع المفاسد في التربية الأخلاقية؟","options":[{"id":"o3","text":"الأمران يتعلقان بالربح المالي وحده"},{"id":"o4","text":"لا تدخل الأخلاق في تقدير المصالح"},{"id":"o1","text":"تشجيع مكارم الأخلاق جلب نفع والتحذير من مساوئها دفع ضرر"},{"id":"o2","text":"التحذير من السوء جلب ضرر والفضيلة دفع منفعة"}],"correct_id":"o1","explanation":"جاء بمقدمة الدرس مثال التشجيع على حسن الأخلاق لجلب المصلحة والتحذير من سيئها لدفع المفسدة.","page":56},{"id":"u02_l02_q123","lesson_id":"u02_l02","difficulty":"hard","prompt":"تاجر يحتج بالربح لتبرير بيع ما نهى الشرع عنه؛ أين الخلل في استدلاله وفق تصنيف المصالح؟","options":[{"id":"o3","text":"يقدم المصلحة العامة على الخاصة بالضرورة"},{"id":"o4","text":"يلتزم بضوابط الشريعة في المكاسب"},{"id":"o1","text":"يتمسك بمصلحة ملغاة لمخالفتها النص وما يترتب عليها من ضرر"},{"id":"o2","text":"يعمل بمصلحة معتبرة لمجرد زيادة الربح"}],"correct_id":"o1","explanation":"مثّل الدرس لملغاة المصلحة بالربح من تجارة الخمر مع تحريمها لضررها.","page":56},{"id":"u02_l02_q126","lesson_id":"u02_l02","difficulty":"medium","prompt":"ما الضابط الأول الذي يمنع قبول اقتراح يبدو نافعًا اقتصاديًا لكنه يخالف حكمًا شرعيًا ثابتًا؟","options":[{"id":"o4","text":"ألا يتطلب إنفاقًا حكوميًا"},{"id":"o2","text":"أن يحقق ربحًا للفرد فقط"},{"id":"o3","text":"أن يلقى تأييدًا سريعًا على الإنترنت"},{"id":"o1","text":"ألا يعارض نصًا أو إجماعًا ثابتًا"}],"correct_id":"o1","explanation":"ذكر الدرس عدم معارضة النص أو الإجماع من ضوابط المصلحة.","page":58},{"id":"u02_l02_q132","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا جاء الترغيب في نظر الخاطب إلى المخطوبة ضمن المصالح المعتبرة؟","options":[{"id":"o4","text":"لأن العادة وحدها تحسم الأحكام"},{"id":"o3","text":"لإلغاء عقد الزواج"},{"id":"o1","text":"لإمكان نشوء الألفة والمودة بين الزوجين"},{"id":"o2","text":"لتحقيق ربح مالي للخاطب"}],"correct_id":"o1","explanation":"ساق الدرس هذا المثال للمصلحة التي اعتبرها الشرع طلبًا للألفة والمودة.","page":56},{"id":"u02_l02_q133","lesson_id":"u02_l02","difficulty":"hard","prompt":"يجني تاجر ربحًا من بيع الخمر ويحتج بذلك على مشروعية نشاطه؛ فما نوع المصلحة التي يدعيها؟","options":[{"id":"o1","text":"مصلحة ملغاة تعارض ضررها حكم الشرع"},{"id":"o2","text":"مصلحة مرسلة ثابتة"},{"id":"o4","text":"حاجة عامة مقدمة على النص"},{"id":"o3","text":"مصلحة معتبرة مطلقًا"}],"correct_id":"o1","explanation":"ضرب الكتاب ربح بائع الخمر مثالًا على مصلحة ضيقة رفضها الشرع.","page":56},{"id":"u02_l02_q138","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا لا تُقبل مصلحة يُتصور تحقيقها بتغيير نصيب وارث منصوص عليه؟","options":[{"id":"o3","text":"لأنها لم تُدرس اقتصاديًا بعد"},{"id":"o1","text":"لمعارضتها حكمًا شرعيًا ثابتًا بنص"},{"id":"o2","text":"لأنها تحتاج مالًا كثيرًا"},{"id":"o4","text":"لأنها منفعة اجتماعية مؤقتة فقط"}],"correct_id":"o1","explanation":"من ضوابط المصلحة عدم معارضة نص أو إجماع.","page":58},{"id":"u02_l02_q143","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا جُعل إنشاء محاكم تنظم حقوق الأسرة مثالًا للمصلحة المرسلة؟","options":[{"id":"o1","text":"لأنها منفعة تنظيميّة لم يرد نص خاص بإنشائها أو منعها"},{"id":"o4","text":"لأن الشرع حرم حفظ الوثائق"},{"id":"o2","text":"لأنها تلغي أحكام الزواج"},{"id":"o3","text":"لأنها تشرّع انتقاص حقوق الأطفال"}],"correct_id":"o1","explanation":"ذكر الدرس إنشاء المحاكم لرعاية حقوق الناس مثالًا للمصلحة المرسلة.","page":57},{"id":"u02_l02_q144","lesson_id":"u02_l02","difficulty":"hard","prompt":"ما وجه الشبه بين جمع القرآن في مصحف واحد وإنشاء الدواوين من حيث الاستدلال بالمصلحة؟","options":[{"id":"o1","text":"إجراءات استحدثها المسلمون لمصلحة عامة دون نص خاص بتفاصيلها"},{"id":"o3","text":"أحكام كانت محرمة ثم ألغيت"},{"id":"o4","text":"ممارسات لا ترتبط بمصلحة الناس"},{"id":"o2","text":"أعمال تناقض نصوص القرآن"}],"correct_id":"o1","explanation":"استدل الكتاب بعمل الصحابة في جمع المصحف وإنشاء الدواوين والقضاء على اعتبار المصالح المرسلة.","page":57},{"id":"u02_l02_q146","lesson_id":"u02_l02","difficulty":"hard","prompt":"احتج صاحب مشروع ربوي بأن الفائدة المالية له مصلحة مؤكدة؛ ما وجه الاعتراض الشرعي بحسب الضوابط؟","options":[{"id":"o4","text":"يُقبل الربا ما دام شائعًا"},{"id":"o3","text":"يحرم حفظ أموال المقترضين"},{"id":"o1","text":"المصلحة الخاصة لا تسوغ ضررًا عامًا ولا مخالفة التحريم"},{"id":"o2","text":"كل ربح خاص يقدّم على المصلحة العامة"}],"correct_id":"o1","explanation":"بيّن الدرس أن الربا يضر عموم الناس ولا تصبح منفعته لبعضهم مسوغًا له.","page":58},{"id":"u02_l02_q147","lesson_id":"u02_l02","difficulty":"medium","prompt":"إذا لم تكن المصلحة المتوقعة إلا وهمًا وكان ضرر الإجراء أكبر، فأي ضابط لم يتحقق؟","options":[{"id":"o4","text":"أن يُستغنى عن النظر في النتائج"},{"id":"o1","text":"أن تكون المصلحة حقيقية لا وهمية"},{"id":"o3","text":"أن يُترك تقدير الضرر للمستفيد وحده"},{"id":"o2","text":"أن تزيد أسعار السلع دائمًا"}],"correct_id":"o1","explanation":"من ضوابط المصلحة أن تكون حقيقية لا موهومة، ولا يطغى الضرر على النفع.","page":58},{"id":"u02_l02_q158","lesson_id":"u02_l02","difficulty":"medium","prompt":"ما العنصر الذي يجب مراجعته قبل تبني قرار تسعير يحمي الناس من الاحتكار؟","options":[{"id":"o2","text":"رغبة محتكر واحد في رفع أرباحه"},{"id":"o4","text":"إلغاء النظر إلى حاجة المشترين"},{"id":"o3","text":"انتشار إشاعة غير موثقة حول الأسعار"},{"id":"o1","text":"تحقق المصلحة العامة ودفع الاستغلال دون مخالفة أحكام الشرع"}],"correct_id":"o1","explanation":"عرض الدرس التسعير المنضبط عند الاستغلال ضمن رعاية مصالح المجتمع.","page":59},{"id":"u02_l02_q172","lesson_id":"u02_l02","difficulty":"medium","prompt":"لماذا عُدّت إباحة أكل الميتة حال الاضطرار من المصالح المعتبرة؟","options":[{"id":"o2","text":"لأن كل محرم يصبح مباحًا دون قيد"},{"id":"o4","text":"لأن المسألة تساوي الرشوة في الحكم"},{"id":"o3","text":"لأن الربح المادي يسبق حفظ الأرواح"},{"id":"o1","text":"لأنها تحفظ النفس من الهلاك عند الضرورة"}],"correct_id":"o1","explanation":"نص الدرس على إباحة الميتة للمضطر حماية لنفسه ضمن المصالح المعتبرة.","page":56},{"id":"u02_l02_q174","lesson_id":"u02_l02","difficulty":"medium","prompt":"ما العلة في قبول إنشاء مؤسسة تحفظ أموال الأيتام في باب المصالح المرسلة؟","options":[{"id":"o2","text":"أنها تخالف النصوص القطعية عمدًا"},{"id":"o1","text":"أنها تحقق مصلحة لا يعارضها الشرع وتحمي حقوق الأيتام"},{"id":"o3","text":"أنها تحقق منفعة خاصة للقائمين عليها فحسب"},{"id":"o4","text":"أنها تلغي حاجة الأيتام إلى الرعاية"}],"correct_id":"o1","explanation":"استدل الكتاب بمؤسسات رعاية أموال الأيتام على المصالح المرسلة التي تدفع الضرر.","page":57},{"id":"u02_l02_q176","lesson_id":"u02_l02","difficulty":"medium","prompt":"لو طالب فرد بإجراء يضر غالبية السكان من أجل ربحه وحده؛ فأي ضابط للمصالح يناقضه طلبه؟","options":[{"id":"o4","text":"أن تستند إلى رأي صاحب الربح وحده"},{"id":"o2","text":"أن تكون المصلحة قابلة للتفسير اللغوي"},{"id":"o1","text":"أن تكون المصلحة عامة لا محصورة في منفعة خاصة ضارة"},{"id":"o3","text":"أن تُذكر في عنوان مستقل"}],"correct_id":"o1","explanation":"يشترط الدرس عموم المصلحة وألا يجلب الحكم نفعًا خاصًا يضر بالناس.","page":58},{"id":"u02_l02_q184","lesson_id":"u02_l02","difficulty":"medium","prompt":"ماذا يعني أن تكون المصلحة عامة عند ترجيح قرار يتعلق بالمرافق العامة؟","options":[{"id":"o4","text":"أن تكون وهمية لا أثر لها في الواقع"},{"id":"o3","text":"أن تخالف نصًا ثابتًا إذا طلب الجمهور"},{"id":"o1","text":"ألا تختزل المنفعة في رغبة فرد على حساب الناس"},{"id":"o2","text":"أن توافق مصلحة واحد مهما ضرّت بالجميع"}],"correct_id":"o1","explanation":"تطلب ضوابط المصالح تحقيق منفعة عامة حقيقية منضبطة بالشرع.","page":58},{"id":"u02_l03_q093","lesson_id":"u02_l03","difficulty":"easy","prompt":"ما موضوع علم الجرح والتعديل؟","options":[{"id":"o3","text":"تقسيم المصالح إلى أنواع"},{"id":"o4","text":"حساب أنصبة الميراث"},{"id":"o1","text":"معرفة أحوال الرواة من حيث القبول والرد"},{"id":"o2","text":"ترتيب الآيات بحسب السور"}],"correct_id":"o1","explanation":"عرف الدرس علم الجرح والتعديل بتقييم حال الرواة.","page":62},{"id":"u02_l03_q094","lesson_id":"u02_l03","difficulty":"medium","prompt":"أي أسلوب يصنف الأحاديث تحت موضوعات الصلاة والزكاة والمعاملات؟","options":[{"id":"o2","text":"التصنيف بحسب اسم المدينة"},{"id":"o4","text":"التصنيف بحسب أعمار المؤلفين"},{"id":"o3","text":"التصنيف بحسب عدد الكلمات"},{"id":"o1","text":"التصنيف بحسب الأبواب الفقهية"}],"correct_id":"o1","explanation":"يسمى الترتيب حسب موضوعات الفقه بالأبواب الفقهية.","page":63},{"id":"u02_l03_q105","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا ورد النهي عن كتابة الحديث أول الدعوة ثم سُمح بالتدوين بعد ذلك؟","options":[{"id":"o2","text":"لمنع نقل السنة إلى الأجيال اللاحقة"},{"id":"o4","text":"لأن السنة لم تكن مصدرًا للتشريع"},{"id":"o1","text":"حفاظًا على تمييز القرآن حتى يستقر تدوينه وحفظه"},{"id":"o3","text":"لإلغاء الاستدلال بالسنة"}],"correct_id":"o1","explanation":"يربط الدرس توقيت الإذن في الكتابة باستقرار حفظ القرآن وتدوينه.","page":61},{"id":"u02_l03_q107","lesson_id":"u02_l03","difficulty":"medium","prompt":"أي خدمة معاصرة للسنة تجمع بين نشر الحديث وتمكين القارئ من التحقق من درجته؟","options":[{"id":"o4","text":"رفض جميع وسائل البحث الحديثة"},{"id":"o1","text":"المواقع المتخصصة التي تعرض الأحاديث وشروحها وأحكامها"},{"id":"o3","text":"الاقتصار على العناوين دون نصوص"},{"id":"o2","text":"تداول الأحاديث بلا إسناد أو تحقق"}],"correct_id":"o1","explanation":"عدد الكتاب من خدمات المواقع الموثوقة بيان الشروح ودرجة الصحة.","page":64},{"id":"u02_l03_q114","lesson_id":"u02_l03","difficulty":"medium","prompt":"لماذا اشتملت بعض كتب الحديث المبكرة على أقوال الصحابة وفتاوى التابعين؟","options":[{"id":"o4","text":"لأنها رتبت الكلمات بحسب الحروف فقط"},{"id":"o1","text":"لأن التدوين جمع الحديث وآثار السلف في أبواب فقهية"},{"id":"o2","text":"لأنها لا تحتوي حديثًا نبويًا"},{"id":"o3","text":"لأن العلماء منعوا جمع آثار الصحابة"}],"correct_id":"o1","explanation":"نصت الصفحة 62 على جمع الأحاديث وأقوال الصحابة وفتاوى التابعين.","page":62},{"id":"u02_l03_q118","lesson_id":"u02_l03","difficulty":"hard","prompt":"أي تفسير يربط الإذن اللاحق بكتابة الحديث بالنهي عنه في بداية الدعوة؟","options":[{"id":"o1","text":"حماية التمييز بين القرآن والحديث أولًا ثم السماح بالتدوين بعد استقرار القرآن"},{"id":"o4","text":"أن تدوين القرآن حصل بعد جميع مصنفات الحديث"},{"id":"o3","text":"أن الصحابة مُنعوا من حفظ السنة مطلقًا"},{"id":"o2","text":"أن النهي سببه عدم أهمية السنة في الإسلام"}],"correct_id":"o1","explanation":"ذكر الدرس الحرص أولًا على عدم الانشغال بغير القرآن ثم الإذن بكتابة السنة.","page":61},{"id":"u02_l03_q119","lesson_id":"u02_l03","difficulty":"hard","prompt":"باحث يمتلك اسم الراوي الصحابي لكنه لا يعرف باب الحديث؛ أي تصنيف يسهل البحث من هذه النقطة؟","options":[{"id":"o1","text":"المسانيد المرتبة على أسماء الصحابة"},{"id":"o4","text":"كتب تاريخ الخلفاء دون روايات"},{"id":"o3","text":"الفهارس المرتبة على المدن"},{"id":"o2","text":"الكتب المبوبة على أبواب الزكاة فقط"}],"correct_id":"o1","explanation":"تصنف المسانيد الأحاديث بحسب أسماء الصحابة لا بحسب موضوع الحديث.","page":63}]$wall_questions$::jsonb)
